<?php
namespace App\Services;use Illuminate\Support\Facades\Http;use RuntimeException;
class BrregService
{
 public function lookup(string $organizationNumber):array{$org=preg_replace('/\D/','',$organizationNumber);if(!preg_match('/^\d{9}$/',$org))throw new RuntimeException('Organisasjonsnummeret må bestå av ni sifre.');$response=Http::acceptJson()->withHeaders(['User-Agent'=>'DekkPilot virksomhetskontroll'])->timeout(10)->get('https://data.brreg.no/enhetsregisteret/api/enheter/'.$org);if($response->status()===404)throw new RuntimeException('Organisasjonsnummeret finnes ikke i Enhetsregisteret.');if($response->status()===410)throw new RuntimeException('Virksomheten er fjernet fra Enhetsregisterets åpne data.');if(!$response->successful())throw new RuntimeException('Brønnøysundregistrene svarer ikke akkurat nå. Prøv igjen senere.');$data=$response->json();if(($data['erSlettet']??false)===true)throw new RuntimeException('Virksomheten er slettet i Enhetsregisteret.');return ['organization_number'=>$org,'name'=>(string)($data['navn']??''),'organization_type'=>data_get($data,'organisasjonsform.kode'),'organization_type_name'=>data_get($data,'organisasjonsform.beskrivelse'),'address'=>implode(' ',data_get($data,'forretningsadresse.adresse',[])),'postal_code'=>data_get($data,'forretningsadresse.postnummer'),'city'=>data_get($data,'forretningsadresse.poststed'),'registered_in_vat_register'=>(bool)($data['registrertIMvaregisteret']??false),'registered_at'=>$data['registreringsdatoEnhetsregisteret']??null];}
}
